"use client";

import { useState } from "react";
import { Settings, MapPin } from "lucide-react";
import { Button } from "@/components/ui/Button";
import { EventCard } from "@/components/EventCard";

const mockUserData = {
  name: "Sarah Johnson",
  username: "@sarahj",
  bio: "Tech enthusiast | Coffee lover | Always up for a good meetup",
  avatar: "https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=400",
  location: "San Francisco, CA",
  followers: 342,
  following: 128,
};

const mockPersonalEvents = [
  {
    id: "p1",
    image: "https://images.unsplash.com/photo-1760642626994-8ebd037f78dc?w=400",
    title: "Weekly Book Club",
    date: "Feb 22, 2026",
    time: "6:00 PM",
    location: "Local Library, SF",
    participants: 8,
    category: "Books",
  },
];

const mockJoinedEvents = [
  {
    id: "1",
    image: "https://images.unsplash.com/photo-1760642626994-8ebd037f78dc?w=400",
    title: "Tech Networking Night",
    date: "Feb 15, 2026",
    time: "7:00 PM",
    location: "Downtown Tech Hub",
    participants: 45,
    category: "Tech",
  },
];

const mockPastEvents = [
  {
    id: "finished-1",
    image: "https://images.unsplash.com/photo-1672841821756-fc04525771c2?w=400",
    title: "Summer Music Fest 2025",
    date: "Aug 10, 2025",
    time: "4:00 PM",
    location: "Golden Gate Park",
    participants: 156,
    category: "Music",
  },
];

export default function DashboardPage() {
  const [mainTab, setMainTab] = useState("posts");
  const [subTab, setSubTab] = useState("personal");

  return (
    <div className="min-h-screen bg-background pb-8">
      {/* Profile Header */}
      <section className="bg-card border-b border-border" aria-label="Perfil de usuario">
        <div className="w-full mx-auto px-6 md:px-8 lg:px-12 py-8 max-w-[1440px]">
          <div className="max-w-2xl mx-auto lg:mx-0">
            <div className="flex items-start gap-5 mb-6">
              <div aria-hidden="true" className="w-24 h-24 rounded-full border-4 border-secondary/20 overflow-hidden bg-primary/10 flex-shrink-0">
                <img src={mockUserData.avatar} alt="" className="w-full h-full object-cover" />
              </div>
              <div className="flex-1">
                <h2 className="text-xl font-bold mb-1">{mockUserData.name}</h2>
                <p className="text-muted-foreground text-sm mb-3">
                  {mockUserData.username}
                </p>
                <div className="flex items-center gap-2 text-sm text-muted-foreground">
                  <MapPin className="w-4 h-4 text-secondary" aria-hidden="true" />
                  <span>{mockUserData.location}</span>
                </div>
              </div>
            </div>

            <p className="text-sm mb-6 leading-relaxed">{mockUserData.bio}</p>

            <div className="flex gap-8 mb-6">
              <div className="text-center">
                <p className="text-xl font-bold text-foreground">{mockUserData.followers}</p>
                <p className="text-sm text-muted-foreground">Seguidores</p>
              </div>
              <div className="text-center">
                <p className="text-xl font-bold text-foreground">{mockUserData.following}</p>
                <p className="text-sm text-muted-foreground">Siguiendo</p>
              </div>
            </div>

            <div className="flex gap-3">
              <Button variant="outline" className="flex-1 md:flex-initial md:px-8 h-12 rounded-xl">
                Editar perfil
              </Button>
              <Button variant="outline" size="icon" aria-label="Ajustes">
                <Settings className="w-5 h-5 text-primary" />
              </Button>
            </div>
          </div>
        </div>
      </section>

      {/* Tabs and Content */}
      <section className="w-full mx-auto px-6 md:px-8 lg:px-12 pt-6 pb-8 max-w-[1440px]" aria-label="Contenido del usuario">

        {/* Main Tablist */}
        <div className="max-w-md mx-auto mb-6 md:max-w-none md:flex md:justify-center md:gap-6" role="tablist">
          <div className="grid grid-cols-2 h-12 bg-card rounded-xl p-1 w-full md:w-64 mb-4 md:mb-0">
            <button
              role="tab"
              aria-selected={mainTab === "posts"}
              onClick={() => { setMainTab("posts"); setSubTab("personal"); }}
              className={`rounded-lg transition-colors font-medium text-sm focus:outline-none focus:ring-2 focus:ring-ring ${
                mainTab === "posts" ? "bg-primary text-primary-foreground shadow-sm" : "text-muted-foreground hover:text-foreground"
              }`}
            >
              Mis posts
            </button>
            <button
              role="tab"
              aria-selected={mainTab === "timeline"}
              onClick={() => { setMainTab("timeline"); setSubTab("upcoming"); }}
              className={`rounded-lg transition-colors font-medium text-sm focus:outline-none focus:ring-2 focus:ring-ring ${
                mainTab === "timeline" ? "bg-primary text-primary-foreground shadow-sm" : "text-muted-foreground hover:text-foreground"
              }`}
            >
              Historial
            </button>
          </div>

          {/* Sub Tablist based on Main Tab */}
          <div className="grid grid-cols-2 h-11 bg-card rounded-lg p-0.5 w-full md:w-56" role="tablist">
            {mainTab === "posts" ? (
              <>
                <button
                  role="tab"
                  aria-selected={subTab === "personal"}
                  onClick={() => setSubTab("personal")}
                  className={`rounded-md transition-colors font-medium text-sm focus:outline-none focus:ring-2 focus:ring-ring ${
                    subTab === "personal" ? "bg-accent text-accent-foreground shadow-sm" : "text-muted-foreground"
                  }`}
                >
                  Personal
                </button>
                <button
                  role="tab"
                  aria-selected={subTab === "joined"}
                  onClick={() => setSubTab("joined")}
                  className={`rounded-md transition-colors font-medium text-sm focus:outline-none focus:ring-2 focus:ring-ring ${
                    subTab === "joined" ? "bg-accent text-accent-foreground shadow-sm" : "text-muted-foreground"
                  }`}
                >
                  Apuntado
                </button>
              </>
            ) : (
              <>
                <button
                  role="tab"
                  aria-selected={subTab === "upcoming"}
                  onClick={() => setSubTab("upcoming")}
                  className={`rounded-md transition-colors font-medium text-sm focus:outline-none focus:ring-2 focus:ring-ring ${
                    subTab === "upcoming" ? "bg-accent text-accent-foreground shadow-sm" : "text-muted-foreground"
                  }`}
                >
                  Próximos
                </button>
                <button
                  role="tab"
                  aria-selected={subTab === "past"}
                  onClick={() => setSubTab("past")}
                  className={`rounded-md transition-colors font-medium text-sm focus:outline-none focus:ring-2 focus:ring-ring ${
                    subTab === "past" ? "bg-accent text-accent-foreground shadow-sm" : "text-muted-foreground"
                  }`}
                >
                  Pasados
                </button>
              </>
            )}
          </div>
        </div>

        {/* Dynamic Event Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 md:gap-7 lg:gap-8 mt-6">
          {(mainTab === "posts" && subTab === "personal" ? mockPersonalEvents : 
            mainTab === "posts" && subTab === "joined" ? mockJoinedEvents :
            mainTab === "timeline" && subTab === "upcoming" ? mockJoinedEvents :
            mockPastEvents).map((event) => (
             <EventCard key={event.id} {...event} />
          ))}
        </div>
      </section>
    </div>
  );
}

"use client";

import { useState } from "react";
import { ArrowLeft, MapPin, Calendar, Users, Share2, Link as LinkIcon, UserPlus } from "lucide-react";
import { useRouter, useParams } from "next/navigation";
import { Button } from "@/components/ui/Button";
import { Badge } from "@/components/ui/Badge";
import Link from "next/link";
import Masonry from "react-responsive-masonry";

export default function ItemDetailPage() {
  const router = useRouter();
  const params = useParams();
  const [showSharePopup, setShowSharePopup] = useState(false);
  const [isJoined, setIsJoined] = useState(false);

  // Mock individual data mapped to any ID to fulfill the page structure
  const event = {
    title: "Tech Networking Night",
    date: "Feb 15, 2026",
    time: "7:00 PM",
    location: "Downtown Tech Hub, 123 Main St, San Francisco, CA 94102",
    participants: 45,
    categories: ["Tech", "Networking", "Professional"],
    image: "https://images.unsplash.com/photo-1760642626994-8ebd037f78dc?w=800",
    description: "Únete a un grupo de mentes curiosas para hablar de nuevas tecnologías, desarrollo y crear conexiones de alto valor.",
    author: { name: "Carlos Ruiz", initials: "CR", avatarColor: "#7209B7" },
    userGallery: [
      "https://images.unsplash.com/photo-1540575467063-178a50c2df87?w=600",
      "https://images.unsplash.com/photo-1515187029135-18ee286d815b?w=600",
      "https://images.unsplash.com/photo-1511578314322-379afb476865?w=600"
    ]
  };

  const handleShare = () => {
    setShowSharePopup(true);
    setTimeout(() => setShowSharePopup(false), 2500);
  };

  return (
    <article className="min-h-screen bg-background pb-20">
      {/* Hero Header */}
      <header className="relative h-72 md:h-96 w-full">
        <img src={event.image} alt="" className="w-full h-full object-cover" />
        <div className="absolute inset-0 bg-gradient-to-t from-background/90 via-transparent to-transparent pointer-events-none" />

        <button
          onClick={() => router.back()}
          className="absolute top-6 left-6 bg-card/90 backdrop-blur-sm rounded-full p-3 shadow-lg hover:bg-card focus:outline-none focus:ring-2 focus:ring-ring transition-colors"
          aria-label="Volver atrás"
        >
          <ArrowLeft className="w-6 h-6 text-foreground" aria-hidden="true" />
        </button>

        <button
          onClick={handleShare}
          className="absolute top-6 right-6 bg-card/90 backdrop-blur-sm rounded-full p-3 shadow-lg hover:bg-card focus:outline-none focus:ring-2 focus:ring-ring transition-colors"
          aria-label="Compartir evento"
        >
          <Share2 className="w-6 h-6 text-foreground" aria-hidden="true" />
        </button>

        {showSharePopup && (
          <div className="absolute top-20 right-6 flex items-center gap-2.5 bg-card border border-border rounded-2xl px-4 py-3 shadow-xl transition-all" role="alert">
            <div className={`w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 bg-primary/10`}>
              <LinkIcon className={`w-4 h-4 text-primary`} aria-hidden="true" />
            </div>
            <span className="text-sm font-medium text-foreground">
              Enlace copiado correctamente
            </span>
          </div>
        )}
      </header>

      {/* Detail Content */}
      <div className="w-full mx-auto px-6 md:px-8 lg:px-12 py-8 max-w-[1000px] -mt-10 relative z-10">
        <div className="bg-card rounded-3xl p-6 md:p-8 shadow-xl border border-border">
          <div className="mb-6">
            <h1 className="text-2xl md:text-3xl font-bold mb-4">{event.title}</h1>
            <div className="flex flex-wrap gap-2 mb-6" aria-label="Categorías del evento">
              {event.categories.map((category) => (
                <Badge key={category} className="bg-accent text-accent-foreground px-4 py-2 rounded-full">
                  {category}
                </Badge>
              ))}
            </div>
          </div>

          <div className="flex items-center gap-3 bg-background rounded-2xl px-5 py-4 mb-8 shadow-sm">
            <div
              className="w-10 h-10 rounded-full flex items-center justify-center flex-shrink-0 text-white text-sm font-semibold"
              style={{ backgroundColor: event.author.avatarColor }}
              aria-hidden="true"
            >
              {event.author.initials}
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-xs text-muted-foreground mb-0.5">Organizado por</p>
              <p className="font-semibold text-sm truncate">{event.author.name}</p>
            </div>
          </div>

          <section className="space-y-4 mb-8 text-sm" aria-label="Información del evento">
            <div className="flex items-start gap-4 p-3 bg-secondary/10 rounded-xl">
              <Calendar className="w-6 h-6 text-primary flex-shrink-0 mt-0.5" aria-hidden="true" />
              <div>
                <p className="font-medium text-base mb-1">{event.date}</p>
                <p className="text-muted-foreground">{event.time}</p>
              </div>
            </div>
            <div className="flex items-start gap-4 p-3 bg-secondary/10 rounded-xl">
              <MapPin className="w-6 h-6 text-secondary flex-shrink-0 mt-0.5" aria-hidden="true" />
              <div>
                <p className="font-medium text-base mb-1">Ubicación</p>
                <p className="text-muted-foreground">{event.location}</p>
              </div>
            </div>
            <div className="flex items-start gap-4 p-3 bg-secondary/10 rounded-xl">
              <Users className="w-6 h-6 text-accent flex-shrink-0 mt-0.5" aria-hidden="true" />
              <div>
                <p className="font-medium text-base mb-1">Asistentes</p>
                <p className="text-muted-foreground">{event.participants} personas apuntadas</p>
              </div>
            </div>
          </section>

          <section aria-labelledby="desc-heading" className="mb-8">
            <h2 id="desc-heading" className="font-semibold text-xl mb-4">Sobre el evento</h2>
            <p className="text-muted-foreground leading-relaxed">
              {event.description}
            </p>
          </section>

          <section aria-labelledby="gallery-heading" className="mb-8">
            <h2 id="gallery-heading" className="font-semibold text-xl mb-4">Galería colaborativa</h2>
            <Masonry columnsCount={2} gutter="12px">
               {event.userGallery.map((url, i) => (
                 <img key={i} src={url} alt={`Imagen ${i+1} del evento`} className="w-full rounded-xl" loading="lazy" />
               ))}
            </Masonry>
          </section>

          <div className="flex gap-4 pt-4 border-t border-border mt-auto">
            <Button 
               size="lg" 
               className={`flex-1 h-16 rounded-2xl text-lg font-semibold shadow-xl transition-all ${isJoined ? 'bg-secondary text-secondary-foreground hover:bg-secondary/90' : ''}`}
               onClick={() => setIsJoined(!isJoined)}
            >
              {isJoined ? "Apuntado" : "Unirme al evento"}
            </Button>
          </div>
        </div>
      </div>
    </article>
  );
}

